-- ============================================================================
-- Gestoría Campalans · Carga inicial de empresas (100 empresas del Excel)
-- ============================================================================
-- Ejecuta este script UNA SOLA VEZ, despues de haber ejecutado schema.sql.
-- Todas las empresas se crean con estado 'No contactado', sin fecha ni
-- observaciones, tal y como pide la especificacion.
-- ============================================================================

on conflict (razon_social_normalizada) where razon_social_normalizada <> 'no encontrado' and razon_social_normalizada <> '' do nothing;
